const ordinal=['1ST','2ND','3RD','4TH','5TH'];
function clock(t){if(!Number.isFinite(t))return '—';const m=Math.floor(t/60),s=(t%60).toFixed(2).padStart(5,'0');return `${m}:${s}`;}
export class RaceHud{
 constructor({onStart,onRestart,onExit}){
  const home=document.querySelector('.home-nav'),start=document.createElement('button');start.id='home-race';start.textContent='RACE ↗';start.onclick=onStart;home.insertBefore(start,home.querySelector('#home-garage'));
  this.root=document.createElement('section');this.root.id='circuit-hud';this.root.hidden=true;this.root.setAttribute('aria-label','Race leaderboard');this.root.innerHTML='<div class="race-dock"><small>SOLANA RACEWAY / 3 LAPS</small><h2 id="circuit-position">1ST <span>/ 5</span></h2><ol id="circuit-board"></ol><div class="race-lap"><b id="circuit-lap">LAP 1 / 3</b><span id="circuit-time">0:00.00</span></div><p id="circuit-best">BEST LAP —</p><p id="circuit-draft"></p><p class="race-gate-key"><span>TARGET</span> · <span>NEXT</span> · <span>CLEARED</span></p><button id="circuit-exit">EXIT RACE</button></div><div id="circuit-countdown" role="status" aria-live="polite"><div class="race-lights"><i></i><i></i><i></i></div><strong></strong></div><div id="circuit-results" hidden><section><small class="race-flag">▦ FINISH ▦</small><h2 id="circuit-result-title">RACE COMPLETE</h2><p id="circuit-total"></p><ol id="circuit-final"></ol><button id="circuit-restart">RACE AGAIN ↗</button><button id="circuit-roam">RETURN TO FREE ROAM</button></section></div>';document.body.append(this.root);
  this.rows=[];for(let i=0;i<5;i++){const li=document.createElement('li');li.innerHTML='<b></b><span></span><em></em>';this.root.querySelector('#circuit-board').append(li);this.rows.push(li);}
  this.title=this.root.querySelector('.race-dock small');this.position=this.root.querySelector('#circuit-position');this.lap=this.root.querySelector('#circuit-lap');this.time=this.root.querySelector('#circuit-time');this.best=this.root.querySelector('#circuit-best');this.draft=this.root.querySelector('#circuit-draft');this.countdown=this.root.querySelector('#circuit-countdown');this.result=this.root.querySelector('#circuit-results');this.lights=this.countdown.querySelectorAll('i');this.countLabel=this.countdown.querySelector('strong');this.lastPhase='';this.acc=0;
  this.root.querySelector('#circuit-exit').onclick=onExit;this.root.querySelector('#circuit-roam').onclick=onExit;this.root.querySelector('#circuit-restart').onclick=onRestart;
 }
 render(dt,race,paused=false){this.root.hidden=!race?.active||paused;if(this.root.hidden)return;this.acc+=dt;if(this.acc<.1&&this.lastPhase===race.phase)return;this.acc=0;const phase=race.phase,me=race.entries[0];this.title.textContent=race.name.toUpperCase()+' / '+race.laps+' LAPS';let position=0;for(let rank=0;rank<5;rank++){const e=race.entries[race.order[rank]],row=this.rows[rank];if(e.index===0)position=rank;row.classList.toggle('you',e.index===0);row.children[0].textContent=ordinal[rank];row.children[1].textContent=(e.index===0?'YOU / ':'AI / ')+e.def.name;const shared=Math.min(me.nextGate,e.nextGate)-1,gap=shared>=0?e.splitTimes[shared]-me.splitTimes[shared]:NaN;row.children[2].textContent=e.index===0?'YOU':Number.isFinite(e.finishTime)?clock(e.finishTime):Number.isFinite(gap)?`${gap>=0?'+':''}${gap.toFixed(1)}s`:'—';}this.position.innerHTML=ordinal[position]+' <span>/ 5</span>';this.lap.textContent=`LAP ${Math.min(race.laps,me.lap+1)} / ${race.laps}`;this.time.textContent=clock(me.lapTime);this.best.textContent='BEST '+clock(me.bestLap)+' · GATE '+((me.nextGate-1)%12+1)+'/12';this.draft.textContent=me.drafting?'SLIPSTREAM · DRAG −35%':'';
  this.countdown.hidden=phase!=='countdown'&&race.time>1;this.countLabel.textContent=phase==='countdown'?String(Math.ceil(race.countdown)):race.time<=1?'GO!':'';for(let i=0;i<3;i++){this.lights[i].classList.toggle('lit',phase!=='countdown'||i<4-Math.ceil(race.countdown));this.lights[i].classList.toggle('go',phase!=='countdown');}
  this.result.hidden=phase!=='finished'&&phase!=='finishing';if(!this.result.hidden){this.root.querySelector('#circuit-result-title').textContent=ordinal[position]+' PLACE';this.root.querySelector('#circuit-total').textContent=`${clock(me.finishTime)} · ${phase==='finishing'?'WAITING FOR THE FIELD':'RACE COMPLETE'}`;const list=this.root.querySelector('#circuit-final');list.replaceChildren();let fastest=Infinity;for(const e of race.entries)fastest=Math.min(fastest,e.bestLap);for(let i=0;i<5;i++){const e=race.entries[race.order[i]],li=document.createElement('li');li.textContent=`${ordinal[i]}  ${e.index===0?'YOU / ':''}${e.def.name}  ${Number.isFinite(e.finishTime)?clock(e.finishTime):phase==='finished'?'DNF':'RACING'}${e.bestLap===fastest?' · FASTEST LAP':''}`;list.append(li);}}
  this.lastPhase=phase;
 }
}
